// The mobile core's binding: the Kotlin UniFFI generates for crates/ngterm-mobile and its libngterm_mobile.so per ABI,
// both written under build/generated by scripts/build-android.sh (never committed), loaded through JNA. Its test
// fixtures hold a fake core for the app's tests, which run without the native library.
plugins {
    alias(libs.plugins.android.library)
    alias(libs.plugins.kover)
}

// relative to the module, as the variant API takes them
val uniffiBindings = "build/generated/uniffi/kotlin"
val nativeLibs = "build/generated/jniLibs"

android {
    namespace = "com.nickalie.ngterm.core"
    compileSdk =
        libs.versions.compileSdk
            .get()
            .toInt()

    defaultConfig {
        minSdk =
            libs.versions.minSdk
                .get()
                .toInt()
        consumerProguardFiles("consumer-rules.pro")
    }

    testFixtures {
        enable = true
    }

    lint {
        warningsAsErrors = true
        abortOnError = true
        checkDependencies = true
        // Checks whose verdict changes with the calendar, not the code: a release elsewhere (a newer library, AGP or
        // Android) would break a pinned build. Upgrades are deliberate edits of gradle/libs.versions.toml.
        disable += setOf("OldTargetApi", "NewerVersionAvailable", "GradleDependency", "AndroidGradlePluginVersion")
    }
}

androidComponents {
    onVariants { variant ->
        variant.sources.kotlin?.addStaticSourceDirectory(uniffiBindings)
        variant.sources.jniLibs?.addStaticSourceDirectory(nativeLibs)
    }
}

kotlin {
    compilerOptions {
        allWarningsAsErrors.set(true)
        progressiveMode.set(true)
    }
}

dependencies {
    // the generated bindings' public types use JNA's (Pointer, Structure)
    api(libs.jna) {
        artifact {
            type = "aar"
        }
    }

    // the generated cleaner's @RequiresApi (uniffi.toml's `android = true`)
    implementation(libs.androidx.annotation)
    // the generated async calls are suspend functions
    api(libs.kotlinx.coroutines.core)
    implementation(libs.kotlinx.coroutines.android)

    testImplementation(libs.junit)
    testImplementation(libs.kotlinx.coroutines.test)
}

// The generated sources come from scripts/build-android.sh, not Gradle: say so instead of failing on missing symbols.
val checkGeneratedCore =
    tasks.register("checkGeneratedCore") {
        val required = listOf(uniffiBindings, nativeLibs).map { layout.projectDirectory.dir(it).asFile }
        doLast {
            val missing = required.filterNot { it.isDirectory }
            check(missing.isEmpty()) {
                "missing ${missing.joinToString()}: run scripts/build-android.sh (it builds the mobile core and " +
                    "generates its Kotlin bindings)"
            }
        }
    }

tasks.named("preBuild") {
    dependsOn(checkGeneratedCore)
}
